mapper.select:

WHERE o.user_id = #{userId} AND a.is_deleted = 0 AND a.shop_id = #{shopId}

    AND a.status = #{status}


    AND (a.order_no LIKE CONCAT('%', #{search}, '%')
         OR o.consignee LIKE CONCAT('%', #{search}, '%')
         OR o.phone LIKE CONCAT('%', #{search}, '%')
         OR EXISTS (SELECT 1 FROM order_items oi
                    WHERE oi.order_id = a.order_id AND oi.product_name LIKE CONCAT('%', #{search}, '%')))


    AND a.${dateField} >= #{startDate}


    AND a.${dateField} <= #{endDate}

ORDER BY a.created_at DESC, a.id DESC


WHERE a.is_deleted = 0 AND a.shop_id = #{shopId}

    AND a.status = #{status}


    AND (a.order_no LIKE CONCAT('%', #{search}, '%')
         OR o.consignee LIKE CONCAT('%', #{search}, '%')
         OR o.phone LIKE CONCAT('%', #{search}, '%')
         OR EXISTS (SELECT 1 FROM order_items oi
                    WHERE oi.order_id = a.order_id AND oi.product_name LIKE CONCAT('%', #{search}, '%')))


    AND a.${dateField} >= #{startDate}


    AND a.${dateField} <= #{endDate}

ORDER BY a.created_at DESC, a.id DESC


WHERE a.order_id = #{orderId} AND a.is_deleted = 0 AND a.shop_id = #{shopId}
ORDER BY a.id DESC
LIMIT 1

