UPDATE after_sales
SET status = #{status}, updated_at = #{updatedAt}
WHERE id = #{id} AND shop_id = #{shopId} AND is_deleted = 0

UPDATE after_sales
SET status = #{status}, merchant_remark = #{merchantRemark}, updated_at = #{updatedAt}
WHERE id = #{id} AND shop_id = #{shopId} AND is_deleted = 0

UPDATE after_sales
SET is_deleted = 1, updated_at = #{now}
WHERE id = #{id} AND shop_id = #{shopId}
